                              onNavigate?.('profile');
                            }
                          }}
                        >
                          {post.author}
                        </strong>
                        <UsersRound size={18} />
                      </div>
                      <span>{post.time}</span>
                    </div>
                    <button type="button" className={styles.moreBtn}>
                      <Ellipsis size={18} />
                    </button>
                  </header>

                  <p className={styles.postTitle}>{post.title}</p>
                  <p className={styles.postSubtitle}>
                    {post.category}
                    {post.periodizations?.[0] ? ` • ${post.periodizations[0]}` : ''}
                  </p>
                  <p className={styles.postText}>{post.text}</p>

                  <footer className={styles.postFooter}>
                    <div>
                      <Heart size={19} /> {post.likes.toLocaleString()}
                    </div>
                    <div>
                      <Repeat2 size={19} /> {post.shares.toLocaleString()}
                    </div>
                    <div>
                      <MessageCircle size={19} /> {post.comments}
                    </div>
                  </footer>

                  <button type="button" className={styles.seeMore}>Виж още</button>
                </article>
              ))
            ) : (
              <article className={styles.emptyState}>
                <p>Няма публикации за избраните филтри.</p>
              </article>
            )}
          </section>

          <aside className={styles.rightPanel}>
            <article className={styles.profileCard}>
              <div className={styles.avatar} aria-hidden="true">👨🏽</div>
              <div>
                <strong
                  className={styles.authorLink}
                  role="button"
                  tabIndex={0}
                  onClick={() => onNavigate?.('profile')}
                  onKeyDown={(event) => {
                    if (event.key === 'Enter' || event.key === ' ') {
                      onNavigate?.('profile');
                    }
                  }}
                >
                  Charles Deo
                </strong>
                <p>@Charles_deo</p>
              </div>
              <button type="button" className={styles.moreBtn}><Ellipsis size={18} /></button>
            </article>

            <article className={styles.friendsCard}>
              <h3>Приятели</h3>
              <ul>
                {FRIENDS.map((friend) => (
                  <li key={friend.email}>
                    <div className={styles.friendAvatar} aria-hidden="true">👤</div>
                    <div>
                      <strong>{friend.name}</strong>
                      <p>{friend.email}</p>
                    </div>
                  </li>
                ))}
              </ul>
            </article>
          </aside>
        </section>
      </main>

      {composerOpen ? (
        <div className={styles.composerOverlay} onClick={() => setComposerOpen(false)}>
          <div className={styles.composerModal} onClick={(event) => event.stopPropagation()}>
            <div className={styles.composerHeader}>
              <button
                type="button"
                className={styles.composerClose}
                onClick={() => setComposerOpen(false)}
              >
                <X size={22} />
              </button>
              <button type="button" className={styles.composerDraftsButton}>
                Чернови
              </button>
            </div>

            <div className={styles.composerBody}>
              <div className={styles.avatar} aria-hidden="true">👨🏽</div>
              <textarea
                value={composerText}
                onChange={(event) => setComposerText(event.target.value)}
                placeholder="Какво се случва?"
                className={styles.composerTextarea}
              />
            </div>

            <div className={styles.composerFooter}>
              <div className={styles.createIcons}>
                <Image size={18} />
                <List size={18} />
                <Smile size={18} />
                <FileText size={18} />
              </div>
              <button type="button" className={styles.composerPostButton}>Публикувай</button>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  );
}
